/// <summary>
/// COC for InventTransferParmLine table.
/// </summary>
[ExtensionOf(tableStr(InventTransferParmLine))]
final class METInventTransferParmLine_Extension
{

}

Method.Source:
/// <summary>
/// Display item cases
/// </summary>
/// <param name = "_inventTransferParmLine">InventTransferParmLine</param>
/// <returns>Qty</returns>
display Qty itemConvertCases(InventTransferParmLine _inventTransferParmLine)
{
    real    sellUOMQty  = 0;
    real    cases       = 0;
    real    factor      = 0;

    UnitOfMeasureSymbol unitUOM = _inventTransferParmLine.METUOM;
    UnitOfMeasureSymbol sellUOM = _inventTransferParmLine.METSellUOM;

    if (unitUOM == sellUOM)
    {
        return _inventTransferParmLine.QtyReceiveNow;
    }
    EcoResReleasedProductUnitConverter  ecoResReleasedProductUnitConverter = EcoResReleasedProductUnitConverter::construct();

    factor = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(1, sellUOM, unitUOM, NoYes::Yes, _inventTransferParmLine.ItemId);

    sellUOMQty = _inventTransferParmLine.QtyReceiveNow / factor;

    cases = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(sellUOMQty, sellUOM, METConstants::unitcase, NoYes::Yes, _inventTransferParmLine.ItemId);

    return cases;
}

/// <summary>
/// Display item UOM qty
/// </summary>
/// <param name = "_inventTransferParmLine">InventTransferParmLine</param>
/// <returns>Qty</returns>
display Qty itemConvertUOM(InventTransferParmLine _inventTransferParmLine)
{
    real    sellUOMQty  = 0;
    real    unitQty     = 0;
    real    factor      = 0;

    UnitOfMeasureSymbol unitUOM = _inventTransferParmLine.METUOM;
    UnitOfMeasureSymbol sellUOM = _inventTransferParmLine.METSellUOM;

    if (unitUOM == sellUOM)
    {
        return _inventTransferParmLine.METCases;
    }
    EcoResReleasedProductUnitConverter  ecoResReleasedProductUnitConverter = EcoResReleasedProductUnitConverter::construct();

    factor      = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(1, METConstants::unitcase, sellUOM, NoYes::Yes, _inventTransferParmLine.ItemId);

    sellUOMQty  = factor * _inventTransferParmLine.METCases;

    unitQty     = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(sellUOMQty, sellUOM, unitUOM, NoYes::Yes, _inventTransferParmLine.ItemId);

    return unitQty;
}

/// <summary>
/// Display item sell UOM
/// </summary>
/// <param name = "_inventTransferParmLine">InventTransferParmLine</param>
/// <returns>UnitOfMeasureSymbol</returns>
display UnitOfMeasureSymbol itemSellUOM(InventTransferParmLine _inventTransferParmLine)
{
    UnitOfMeasureSymbol     ret = '';
    InventTransferTable     inventTransferTable = InventTransferTable::find(_inventTransferParmLine.TransferId);

    ret = this.getSellUOM(_inventTransferParmLine.ItemId, inventTransferTable.InventLocationIdFrom);

    return ret;
}

/// <summary>
/// Get sell UOM
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventLocationId">InventLocationId</param>
/// <returns>UnitOfMeasureSymbol</returns>
public UnitOfMeasureSymbol getSellUOM(ItemId _itemId, InventLocationId _inventLocationId)
{
    InventItemSalesSetup        inventItemSalesSetup;
    InventDim                   inventDim;
    UnitOfMeasureSymbol         ret;

    if (_itemId)
    {
        select firstonly inventItemSalesSetup
            where inventItemSalesSetup.ItemId == _itemId
        exists join inventDim
            where inventItemSalesSetup.InventDimId == inventDim.inventDimId
                && inventDim.InventSiteId == InventLocation::find(_inventLocationId).InventSiteId;

        if (inventItemSalesSetup.METSalesUnit)
        {
            ret = inventItemSalesSetup.METSalesUnit;
        }
        else if (!inventItemSalesSetup.METSalesUnit && !ret)
        {
            inventItemSalesSetup = InventItemSalesSetup::find(_itemId, METConstants::AllowBlank);

            ret = inventItemSalesSetup.METSalesUnit;
        }
        else if (!ret)
        {
            InventTableModule  inventTableModule = InventTableModule::find(_itemId, ModuleInventPurchSales::Sales);

            ret = inventTableModule.UnitId;
        }
    }
    return ret;
}
